/* ปกแบบ "sealstampframe" = ภาพในกรอบเอกสารราชการสีขาวงาช้าง ขอบเส้นคู่สีน้ำเงินเข้ม และตราประทับวงกลมสีแดงชาด "บจก." พร้อมวงแหวนหยัก ประทับทับมุมล่างขวา (คู่มือ company-debt-director) */
.gd-cover[data-layout="sealstampframe"] .gd-cover-art { overflow: visible; border: 6px double #24407a; border-radius: 4px; background: #fbf8ee; box-shadow: 0 6px 12px rgba(20,30,70,.2); }
.gd-cover[data-layout="sealstampframe"] .gd-cover-art .gd-scene { border-radius: 1px; }
.gd-cover[data-layout="sealstampframe"] .gd-cover-art::after { content: "บจก."; position: absolute; right: -12px; bottom: -12px; z-index: 3; pointer-events: none; width: 38px; height: 38px; display: flex; align-items: center; justify-content: center; font: 900 9px/1 sans-serif; color: #c8323a; background: radial-gradient(circle, rgba(255,250,245,.92) 0 13px, #c8323a 13.5px 15px, rgba(255,250,245,.92) 15.5px 17px, transparent 17.5px), repeating-conic-gradient(#c8323a 0 6deg, transparent 6deg 12deg); border-radius: 50%; transform: rotate(-16deg); opacity: .92; }
